/**
 * =============================================================================
 * KS-256 — check-spec-examples: E5–E7, the example-block rules
 * =============================================================================
 *
 * These apply only inside `example:` / `examples:` blocks, because that is
 * where a field NAME is in scope — and a category-3 (person-shaped) or
 * category-4 (infrastructure) verdict is meaningless without one.
 *
 * For an object-valued example the name comes from the path, one key per
 * recursion step. For a SCALAR one the path ends on the literal `example`, so
 * the name has to be carried in from `collectExamples` — otherwise E5, E8 and
 * E9 all test the string `"example"` against their field patterns, match
 * nothing, and pass every path parameter and scalar property in the document
 * (KS-677).
 * =============================================================================
 */

import { isAllowed } from './allowlist.mjs';
import { leafName, record } from './finding.mjs';
import {
  BENIGN_SHAPES,
  FIXTURE_ID_VALUES,
  FIXTURE_PERSON_VALUES,
  HIGH_ENTROPY_RE,
  IDENTIFIER_FIELD_RE,
  IDENTIFIER_VALUE_RE,
  INFRA_FIELDS,
  MOCK_SIGNATURE_MARKER,
  PASSWORD_FIELD_RE,
  isPersonField,
  SYNTHESISED_PLACEHOLDER_RE,
} from './contract.mjs';

/**
 * Walk one example value, applying E5–E7.
 *
 * @param node - the example value (any JSON shape).
 * @param docPath - dotted path to `node` within the spec.
 * @param allow - validated allowlist entries.
 * @param findings - caller-owned array, appended to in place.
 * @param ownerField - the field this example is declared on, when the path
 *   cannot say. Propagated through arrays — `tags: ["…"]` is still the `tags`
 *   field — but NOT into objects, where each key names itself.
 */
export function sweepExample(node, docPath, allow, findings, ownerField) {
  if (node === null || node === undefined) return;

  if (typeof node === 'string') {
    const field = ownerField ?? leafName(docPath);
    checkPersonValue(node, docPath, allow, findings, field);
    checkHighEntropy(node, docPath, allow, findings);
    checkAccountId(node, docPath, allow, findings, field);
    checkUsableCredential(node, docPath, allow, findings, field);
    return;
  }

  if (Array.isArray(node)) {
    node.forEach((value, index) =>
      sweepExample(value, `${docPath}.${index}`, allow, findings, ownerField));
    return;
  }

  if (typeof node === 'object') {
    for (const [key, value] of Object.entries(node)) {
      checkInfraField(key, value, `${docPath}.${key}`, allow, findings);
      sweepExample(value, `${docPath}.${key}`, allow, findings);
    }
  }
}

/** E5 — a person-shaped field carrying anything but a fixture value. */
function checkPersonValue(text, docPath, allow, findings, field) {
  if (!isPersonField(field)) return;
  if (FIXTURE_PERSON_VALUES.has(text)) return;
  // A `<placeholder>` is a deliberate mask, not a value — categories 1 and 2.
  if (text.startsWith('<')) return;
  if (isAllowed(allow, 'E5', docPath)) return;

  record(findings, 'E5', docPath, text,
    `person-shaped field "${field}" must use a value from the fixture set (examples/fixtures.ts FX)`,
    field);
}

/** E7 — a long unbroken high-entropy blob that is not a known benign shape. */
function checkHighEntropy(text, docPath, allow, findings) {
  if (!HIGH_ENTROPY_RE.test(text)) return;
  if (BENIGN_SHAPES.some((shape) => shape.test(text))) return;
  if (text.endsWith(MOCK_SIGNATURE_MARKER)) return;
  // `example-<longFieldName>` is the synthesiser's stand-in. It is long and
  // unbroken enough to look high-entropy, but it is the least secret string in
  // the document — the same exemption E8 makes.
  if (SYNTHESISED_PLACEHOLDER_RE.test(text)) return;
  if (isAllowed(allow, 'E7', docPath)) return;

  record(findings, 'E7', docPath, text,
    'long high-entropy value — key/token shaped; publish a named placeholder instead');
}

/**
 * E8 — an identifier literal that is not in the fixture set.
 *
 * This is the id analogue of E5. A seeded user id names a live, loginable
 * account exactly as its email does, and nothing in E1–E7 looks at
 * identifiers — which is how `a0000000-0000-4000-8000-000000000010`
 * (`demo@secuura.io`'s id) reached the published spec in four places.
 *
 * Scoped to fields that NAME an identifier and values that LOOK like one, so
 * a free-text field that happens to contain a dash is not swept up.
 */
function checkAccountId(text, docPath, allow, findings, field) {
  if (!IDENTIFIER_FIELD_RE.test(field)) return;
  if (!IDENTIFIER_VALUE_RE.test(text)) return;
  if (FIXTURE_ID_VALUES.has(text)) return;
  // A `<placeholder>` is a deliberate mask, and `example-…` is the
  // synthesiser's stand-in; neither is an identifier literal.
  if (text.startsWith('<') || SYNTHESISED_PLACEHOLDER_RE.test(text)) return;
  if (isAllowed(allow, 'E8', docPath)) return;

  record(findings, 'E8', docPath, text,
    `identifier field "${field}" carries a literal that is not in the fixture set — ` +
    'a seeded id names a live account (examples/fixtures.ts FX)',
    field);
}

/**
 * E9 — a password-shaped field carrying a usable value.
 *
 * Distinct from every other rule here: the value is not leaked FROM anything,
 * it CREATES something. Schemathesis executes request examples, so a published
 * `{ email, password }` pair registers that account and the spec then documents
 * working credentials. E1–E8 all pass such a pair — reserved domain, no seeded
 * account, no `*123` literal, nothing high-entropy.
 *
 * A `<placeholder>` is accepted: it is the login example's convention and is
 * not a credential anyone can depend on.
 */
function checkUsableCredential(text, docPath, allow, findings, field) {
  if (!PASSWORD_FIELD_RE.test(field)) return;
  if (text.startsWith('<')) return;
  if (isAllowed(allow, 'E9', docPath)) return;

  record(findings, 'E9', docPath, text,
    `password field "${field}" carries a usable value — Schemathesis EXECUTES request ` +
    'examples, so this registers a real account and publishes its credentials; use a `<…>` placeholder',
    field);
}

/** E6 — an infrastructure field carrying any example at all. */
function checkInfraField(key, value, docPath, allow, findings) {
  if (!INFRA_FIELDS.has(key.toLowerCase())) return;
  if (isAllowed(allow, 'E6', docPath)) return;

  record(findings, 'E6', docPath, String(value),
    `infrastructure field "${key}" must not carry an example (examples/masking.ts CATEGORY 4)`);
}

