/**
 * KS-488 C-5 — outbound email header hygiene.
 *
 * Three separable claims, each with cases that must SUCCEED alongside the ones
 * that must be refused. A sanitiser that returned '' for everything, or an
 * allow-list that refused everyone, would satisfy the rejection half on its own.
 *
 * Note on what this suite does NOT claim: the CRLF strip is defence in depth,
 * not a fix for a live vulnerability. Measured 2026-08-14, nodemailer Q-encodes
 * a CRLF-bearing subject into one folded header and no injected header appears;
 * the ACS path sends a JSON REST body and has no header stream at all. The
 * guard is here so that stays true if the transport is ever swapped.
 */
import { describe, it, expect } from 'vitest';
import {
  sanitizeHeaderText,
  headerTextWasUnsafe,
  escapeHtmlText,
  parseRecipientAllowlist,
  isRecipientAllowed,
  MAX_HEADER_TEXT_LENGTH,
} from '../security/email-header-guard';

describe('sanitizeHeaderText', () => {
  it('strips the CRLF that a header-injection payload depends on', () => {
    const evil = 'Invoice\r\nBcc: attacker@evil.example\r\nX-Injected: yes';
    const out = sanitizeHeaderText(evil);

    expect(out).not.toContain('\r');
    expect(out).not.toContain('\n');
    expect(out).toBe('Invoice Bcc: attacker@evil.example X-Injected: yes');
  });

  it('strips bare LF and bare CR, not just the pair', () => {
    expect(sanitizeHeaderText('a\nb')).toBe('a b');
    expect(sanitizeHeaderText('a\rb')).toBe('a b');
  });

  it('strips NUL and the rest of the C0 range, and DEL', () => {
    expect(sanitizeHeaderText('a\u0000b\u0001c\u001Fd\u007Fe')).toBe('a b c d e');
  });

  // --- cases that must SUCCEED ---
  it('leaves an ordinary document title exactly as it was', () => {
    const title = 'Q3 2026 Board Minutes (final)';
    expect(sanitizeHeaderText(title)).toBe(title);
  });

  it('preserves non-ASCII text — this is a header sanitiser, not an ASCII filter', () => {
    expect(sanitizeHeaderText('Beschlüsse — 決議 — Ω')).toBe('Beschlüsse — 決議 — Ω');
  });

  it('collapses the whitespace a strip leaves behind rather than doubling it', () => {
    expect(sanitizeHeaderText('a \r\n b')).toBe('a b');
  });

  it('bounds a pathological title and marks the truncation', () => {
    const long = 'x'.repeat(MAX_HEADER_TEXT_LENGTH + 50);
    const out = sanitizeHeaderText(long);

    expect(out).toHaveLength(MAX_HEADER_TEXT_LENGTH);
    expect(out.endsWith('…')).toBe(true);
  });

  it('handles null, undefined and non-strings without throwing', () => {
    expect(sanitizeHeaderText(null)).toBe('');
    expect(sanitizeHeaderText(undefined)).toBe('');
    expect(sanitizeHeaderText(42)).toBe('42');
  });
});

describe('headerTextWasUnsafe', () => {
  it('reports true only when something was actually carried', () => {
    expect(headerTextWasUnsafe('Invoice\r\nBcc: x@y.z')).toBe(true);
    expect(headerTextWasUnsafe('Q3 2026 Board Minutes')).toBe(false);
    expect(headerTextWasUnsafe(42)).toBe(false);
  });
});

describe('escapeHtmlText', () => {
  it('defuses an anchor smuggled into a document title', () => {
    const out = escapeHtmlText('<a href="https://evil.example">Click here</a>');

    expect(out).not.toContain('<a ');
    expect(out).toContain('&lt;a href=&quot;https://evil.example&quot;&gt;');
  });

  it('escapes quotes, because several sites are attribute values', () => {
    expect(escapeHtmlText('" onmouseover="x')).toBe('&quot; onmouseover=&quot;x');
    expect(escapeHtmlText("' onmouseover='x")).toBe('&#39; onmouseover=&#39;x');
  });

  it('escapes the ampersand first, so an escape is not double-encoded wrongly', () => {
    expect(escapeHtmlText('Tom & Jerry <b>')).toBe('Tom &amp; Jerry &lt;b&gt;');
  });

  // --- cases that must SUCCEED ---
  it('leaves ordinary title text untouched', () => {
    expect(escapeHtmlText('Q3 2026 Board Minutes (final)')).toBe('Q3 2026 Board Minutes (final)');
  });

  it('leaves a legitimate platform URL usable', () => {
    const url = 'https://demo-pk.secuura.net/verify/abc123?token=xyz';
    expect(escapeHtmlText(url)).toBe(url);
  });
});

describe('parseRecipientAllowlist', () => {
  it('treats absent, empty and whitespace-only specs as "no allow-list"', () => {
    expect(parseRecipientAllowlist(undefined)).toEqual([]);
